flags.typeql:
match
$e isa offshore_entity, has incorporation_date 2006-03-23;
fetch {
  "entity_name": $e.name,
  "incorporation_date": $e.incorporation_date
};

match
$e isa offshore_entity, has incorporation_date $d;
$d >= 2006-01-01;
$d <= 2006-01-31;
fetch {
  "name": $e.name,
  "incorporation_date": $d
};

match
$e isa offshore_entity, has incorporation_date 2006-03-23;
fetch {
  "entity_name": $e.name,
  "former_name": $e.former_name
};

match
$e isa offshore_entity, has name $name, has struck_off_date $d;
$d >= 2013-02-01;
$d < 2013-03-01;
fetch { "name": $name };

match
$e isa offshore_entity, has incorporation_date $d, has service_provider $sp;
$d >= 2006-01-01;
$d < 2007-01-01;
fetch {
  "entity_name": $e.name,
  "service_provider": $sp
};

match
$e isa offshore_entity, has incorporation_date $inc_date;
$inc_date >= 2006-01-01;
$inc_date < 2007-01-01;
fetch {
  "entity_name": $e.name,
  "current_status": $e.status
};

match
$e isa offshore_entity,
  has struck_off_date $date,
  has name $name,
  has service_provider $sp;
$date >= 2013-02-01;
$date <= 2013-02-28;
fetch {
  "entity_name": $name,
  "service_provider": $sp
};

match
$e isa offshore_entity, has inactivation_date $d, has name $n, has status $s;
$d >= 2013-02-01;
$d < 2013-03-01;
fetch {
  "entity_name": $n,
  "last_known_status": $s
};

match
$e isa offshore_entity,
  has name $n,
  has incorporation_date $inc,
  has struck_off_date $struck;
$inc >= 2013-01-01;
$inc < 2014-01-01;
$struck >= 2013-01-01;
$struck < 2014-01-01;
fetch {
  "entity_name": $n,
  "incorporation_date": $inc,
  "struck_off_date": $struck
};

match
$e isa offshore_entity, has incorporation_date $d, has status "Active";
$d >= 2007-01-01; $d <= 2007-12-31;
officer_of (officer: $o, offshore_entity: $e);
$o isa officer;
fetch {
  "officer_name": $o.name,
  "entity_name": $e.name
};

match
$e isa offshore_entity, has status "Defaulted", has name $entity_name;
registered_address (registrant: $e, registered_addr: $a);
$a has address $last_known_address;
{
  $e has inactivation_date $d1;
  $d1 >= 2013-01-01;
  $d1 <= 2013-12-31;
} or {
  $e has struck_off_date $d2;
  $d2 >= 2013-01-01;
  $d2 <= 2013-12-31;
};
fetch {
  "entity_name": $entity_name,
  "last_known_address": $last_known_address
};

match
$e isa offshore_entity, has incorporation_date $d, has name $n, has status $s;
$d >= 2006-01-01;
$d <= 2006-01-31;
fetch {
  "entity_name": $n,
  "last_known_status": $s
};

match
$e isa offshore_entity,
  has incorporation_date $inc_date,
  has status $status;
$inc_date >= 2006-03-01;
$inc_date < 2006-04-01;
{ $status == "Defaulted"; } or { $status == "Inactive"; } or { $status == "Struck Off"; } or { $status == "Dissolved"; };
fetch {
  "entity_name": $e.name,
  "incorporation_date": $inc_date,
  "status": $status
};

match
$e isa offshore_entity, has jurisdiction "SAM", has struck_off_date $d;
$d >= 2013-01-01;
$d < 2014-01-01;
fetch {
  "entity_name": $e.name,
  "struck_off_date": $d
};

match
$e isa offshore_entity,
  has service_provider "Mossack Fonseca",
  has incorporation_date $d,
  has name $n;
$d >= 2006-01-01;
$d <= 2006-12-31;
fetch {
  "name": $n,
  "incorporation_date": $d,
  "service_provider": $e.service_provider
};

match
$a isa postal_address, has address $addr;
{
  $r1 isa offshore_entity;
  $r2 isa offshore_entity;
  registered_address (registered_addr: $a, registrant: $r1);
  registered_address (registered_addr: $a, registrant: $r2);
  not { $r1 is $r2; };
} or {
  $r1 isa officer;
  $r2 isa officer;
  registered_address (registered_addr: $a, registrant: $r1);
  registered_address (registered_addr: $a, registrant: $r2);
  not { $r1 is $r2; };
};
limit 3;
fetch { "sharedAddress": $addr };

match
$e isa offshore_entity, has struck_off_date $d, has name $n;
$d >= 2013-01-01;
$d <= 2013-12-31;
limit 5;
fetch {
  "name": $n,
  "struck_off_date": $d
};

match
$e isa offshore_entity;
$a isa postal_address, has countries "Hong Kong";
registered_address (registrant: $e, registered_addr: $a);
limit 5;
fetch {
  "entity_name": $e.name,
  "entity_address": $a.address
};

match
$e isa offshore_entity, has incorporation_date $d, has name $n;
$d >= 2006-01-01;
$d <= 2006-12-31;
fetch {
  "entity_name": $n,
  "incorporation_date": $d
};

match
$e isa offshore_entity, has inactivation_date $d, has name $n;
$d >= 2014-02-01;
$d <= 2014-02-28;
fetch {
  "entity_name": $n,
  "inactivation_date": $d
};

match
$e isa offshore_entity, has closed_date $cd, has name $n;
$cd >= 2012-11-01;
$cd <= 2012-11-30;
fetch {
  "entity_name": $n,
  "closed_date": $cd
};

match
$e isa offshore_entity, has struck_off_date $d, has name $n;
$d >= 2013-02-01;
$d <= 2013-02-28;
fetch { "name": $n };

match
$e isa offshore_entity, has incorporation_date $d, has name $n;
$d >= 2006-03-01;
$d <= 2006-03-31;
registered_address (registrant: $e, registered_addr: $a);
$a has address $addr;
fetch {
  "entity_name": $n,
  "registered_address": $addr
};

match
$e isa offshore_entity, has inactivation_date $d, has name $en;
$d >= 2012-02-01;
$d <= 2012-02-29;
$o isa officer, has name $on;
officer_of (officer: $o, offshore_entity: $e);
fetch {
  "officer_name": $on,
  "entity_name": $en
};

match
$e isa offshore_entity, has incorporation_date $d, has name $en;
$o isa officer, has name $on;
officer_of (officer: $o, offshore_entity: $e);
$d >= 2006-01-01;
$d <= 2006-12-31;
fetch {
  "OfficerName": $on,
  "EntityName": $en
};

match
$e isa offshore_entity;
$target has name "Top Games Holdings Inc.";
same_name_as (named_source: $e, named_target: $target);
fetch {
  "entity_name": $e.name,
  "incorporation_date": $e.incorporation_date
};

match
$e isa offshore_entity, has incorporation_date $date, has name $name, has country_codes $cc;
$date >= 2006-01-01;
$date < 2006-02-01;
fetch {
  "entity_name": $name,
  "country_codes": $cc
};

match
$e isa offshore_entity, has name $n, has incorporation_date $inc, has struck_off_date $struck;
$inc >= 2012-01-01;
$inc <= 2012-12-31;
$struck >= 2012-01-01;
$struck <= 2012-12-31;
fetch { "name": $n };

match
$e isa offshore_entity,
  has incorporation_date $d,
  has status "Defaulted",
  has name $name;
$d >= 2006-01-01;
$d < 2007-01-01;
fetch {
  "entity_name": $name,
  "incorporation_date": $d,
  "status": $e.status
};

match
$e isa offshore_entity, has name $n, has struck_off_date $d;
$d >= 2013-02-01;
$d <= 2013-02-28;
fetch {
  "name": $n,
  "struck_off_date": $d
};

match
$e isa offshore_entity,
  has struck_off_date $date,
  has former_name $fn,
  has name $n;
$date >= 2012-02-01;
$date <= 2012-02-29;
fetch {
  "entity_name": $n,
  "former_name": $fn,
  "struck_off_date": $date
};

match $e isa offshore_entity, has service_provider "Mossack Fonseca", has struck_off_date $sd;
$sd >= 2013-01-01;
$sd <= 2013-12-31;
fetch { "name": $e.name };

match
$e isa offshore_entity,
  has name $name,
  has struck_off_date $date;
$date >= 2014-01-01;
$date < 2015-01-01;
fetch {
  "entity_name": $name,
  "struck_off_date": $date
};

match
$e isa offshore_entity,
    has incorporation_date $d,
    has service_provider "Mossack Fonseca";
$d >= 2006-01-01;
$d < 2007-01-01;
fetch {
    "entity_name": $e.name,
    "incorporation_date": $d,
    "service_provider": $e.service_provider
};

match
$e isa offshore_entity, has name $name, has incorporation_date $inc_date;
$inc_date == 2006-03-23;
fetch {
  "entity_name": $name,
  "incorporation_date": $inc_date
};

match
$e isa offshore_entity, has status "Defaulted", has inactivation_date $d;
$d >= 2013-01-01;
$d <= 2013-12-31;
fetch { "name": $e.name };

match
$e isa offshore_entity, has struck_off_date $d, has name $n;
$d >= 2013-02-01;
$d <= 2013-02-28;
fetch {
  "entity_name": $n,
  "struck_off_date": $d
};
